# T14 – Opisy prywatne, etap 6: edycja szablonów (wersje, przywracanie, nowe pola, walidacja, własne procedury, duplikat,
#       ukrywanie), zapisana wizyta zachowuje wersję szablonu, ulubione, zestawy (tworzenie, kolejność – także przeciąganie,
#       ceny wg cennika, użycie w wizycie, duplikat, usuwanie, wyszukiwanie), tryb szybkiej wizyty („Kopiuj i zapisz”)
import sys,os; sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from h import *
import re
def ready(pg): pg.wait_for_function("typeof S!=='undefined'&&S.ready===true",timeout=15000)
def tab(pg,k): pg.click(f'#tabs button[data-tab="{k}"]'); pg.wait_for_timeout(80)
def fid(pg,i,k): return '#f_'+pg.evaluate(f"V.items[{i}].u")+'_'+k
def txt(pg): return pg.evaluate("curText()")
def tx(pg,sel): return clean(pg.inner_text(sel)).replace('\n',' ')
def fo(pg,key):   # otwórz kartę pola o danym kodzie w edytorze
    j=pg.evaluate(f"S.ed.def.fields.findIndex(f=>f.k==='{key}')"); pg.click(f'#fe-{j} button[data-a="fopen"]'); return j
with sync_playwright() as p:
    b=launch(p); t=T(); errs=[]
    ctx=b.new_context(viewport={'width':1366,'height':950}); ctx.grant_permissions(['clipboard-read','clipboard-write']); login(ctx)
    pg=ctx.new_page(); pg.on('pageerror',lambda e: errs.append(str(e)))
    pg.goto(PRYW); ready(pg)
    # ---------- edycja szablonu: nowe pole, nazwa, nowa wersja ----------
    tab(pg,'tpl'); pg.click('#t-zach-staly button[data-a="tedit"]')
    t.chk('edytor: wszystkie pola zwinięte do jednej linii, podgląd pustego formularza z [UZUPEŁNIJ]', pg.locator('.pw-fec').count()==pg.evaluate("S.ed.def.fields.length")>=13 and '[UZUPEŁNIJ: Ząb (FDI)]' in pg.inner_text('#e_prev'))
    t.chk('brak fałszywego ostrzeżenia o polach używanych tylko warunkowo (leki)', 'nieistniejących' not in pg.inner_text('#e_prev'))
    pg.click('button[data-a="fadd"]'); j=pg.evaluate("S.ed.def.fields.length-1")
    pg.fill(f'#fe_{j}_l','Kontrola za'); pg.fill(f'#fe_{j}_k','kontrola'); pg.press(f'#fe_{j}_k','Tab'); pg.wait_for_timeout(100)
    t.chk('po zmianie kodu fokus przechodzi dalej (Tab), kod zapisany', pg.evaluate("document.activeElement.id")==f'fe_{j}_t' and pg.evaluate(f"S.ed.def.fields[{j}].k")=='kontrola', pg.evaluate("document.activeElement.id"))
    tpl=pg.input_value('#e_tpl'); pg.fill('#e_tpl',tpl+'\n{?kontrola}Kontrola za {kontrola}.{/kontrola}')
    pg.fill('#e_name','Wypełnienie – ząb stały')
    t.chk('podgląd „pola wypełnione” pokazuje nowe zdanie', 'Kontrola za «Kontrola za».' in pg.inner_text('#e_prev'), pg.inner_text('#e_prev')[-200:])
    pg.click('#e_save'); pg.wait_for_timeout(300)
    row=tx(pg,'#t-zach-staly')
    t.chk('zapis: nowa wersja v2, nazwa zmieniona, oznaczenie „zmieniona”', 'Wypełnienie – ząb stały' in row and 'v2' in row and 'zmieniona' in row, row)
    raw=pg.evaluate("G.store('kv').raw('pryw:katalog')")
    t.chk('szablony użytkownika zapisane zaszyfrowane', bool(re.fullmatch(r'v1:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+',raw or '')))
    # zmiana kodu pola przenosi się do szablonu
    pg.click('#t-zach-staly button[data-a="tedit"]'); j=fo(pg,'kontrola'); pg.fill(f'#fe_{j}_k','kontrola_za'); pg.press(f'#fe_{j}_k','Tab'); pg.wait_for_timeout(100)
    t.chk('zmiana kodu pola zmienia też odwołania w tekście szablonu', '{?kontrola_za}Kontrola za {kontrola_za}.{/kontrola_za}' in pg.input_value('#e_tpl'))
    pg.click('button[data-a="ecancel"]')
    t.chk('„Anuluj” nie zapisuje zmian (dalej v2, kod „kontrola”)', 'v2' in tx(pg,'#t-zach-staly') and pg.evaluate("PROC.get('zach-staly').fields.some(f=>f.k==='kontrola')"))
    # ---------- wizyta z nową wersją; zapis zachowuje wersję ----------
    tab(pg,'wiz'); pg.fill('#p_q','ząb stały'); pg.wait_for_timeout(250); pg.click('button[data-add="zach-staly"]')
    pg.fill(fid(pg,0,'zab'),'26'); pg.fill(fid(pg,0,'rozp'),'próchnica zębiny (K02.1)'); pg.fill(fid(pg,0,'mat'),'kompozyt'); pg.fill(fid(pg,0,'kontrola'),'6 miesięcy')
    t.chk('wizyta: nowe pole z szablonu v2 trafia do opisu', txt(pg).endswith('Wypełnienie: kompozyt.\nKontrola za 6 miesięcy.'), txt(pg))
    pg.fill('#v_ini','ab'); pg.click('#b_save'); pg.wait_for_function("S.visits.size===1"); vid=pg.evaluate("V.id"); saved=txt(pg)
    tab(pg,'tpl'); pg.click('#t-zach-staly button[data-a="tedit"]')
    pg.fill('#e_tpl',pg.input_value('#e_tpl').replace('Wypełnienie: {mat}','Materiał: {mat}')); pg.click('#e_save'); pg.wait_for_timeout(300)
    t.chk('kolejna wersja (v3)', 'v3' in tx(pg,'#t-zach-staly'))
    tab(pg,'hist'); pg.click(f'#h-{vid} button[data-a="hopen"]'); pg.wait_for_timeout(300)
    t.chk('otwarta zapisana wizyta: tekst wg wersji z dnia zapisu (v2) + informacja o nowszej wersji', txt(pg)==saved and 'Szablon w wersji z dnia zapisu (v2); aktualna: v3' in pg.inner_text('#items') and not pg.evaluate("dirty()"))
    t.chk('…historia pokazuje zapisany tekst bez zmian', pg.evaluate(f"G.store('opisy').get('{vid}')")['txt']==saved)
    pg.click('#items button[data-a="usecur"]'); pg.wait_for_timeout(150)
    t.chk('„Użyj aktualnej wersji” → tekst wg v3 (zmiana do zapisania)', 'Materiał: kompozyt.' in txt(pg) and pg.evaluate("dirty()"))
    pg.click('#b_new'); pg.click('#b_new')
    # ---------- przywrócenie wersji ----------
    tab(pg,'tpl'); pg.click('#t-zach-staly button[data-a="tedit"]')
    hv=[clean(x) for x in pg.locator('details .pw-tl b').all_text_contents()] if pg.locator('details').count() else []
    t.chk('historia wersji: v2 i v1', hv==['v2','v1'], hv)
    pg.click('details summary'); pg.click('details .pw-tl:has-text("v1") button[data-a="erestore"]'); pg.click('details .pw-tl:has-text("v1") button[data-a="erestore"]'); pg.wait_for_timeout(300)
    pg.click('button[data-a="ecancel"]'); row=tx(pg,'#t-zach-staly')
    t.chk('przywrócenie v1 zapisuje ją jako v4; szablon znów domyślny (bez „zmieniona”)', 'v4' in row and 'zmieniona' not in row and 'Leczenie zachowawcze – ząb stały' in row, row)
    # ---------- nowa procedura: walidacja ----------
    pg.click('#t_new'); j=fo(pg,'rozp'); pg.fill(f'#fe_{j}_k','zab'); pg.press(f'#fe_{j}_k','Tab'); pg.wait_for_timeout(100); pg.fill('#e_name','Wybielanie nakładkowe')
    pg.click('#e_save'); pg.wait_for_timeout(150)
    t.chk('walidacja: powtórzony kod pola blokuje zapis z komunikatem', 'Kod „zab” powtarza się.' in pg.inner_text('#e_prev') and not pg.evaluate("ALL.some(p=>p.name==='Wybielanie nakładkowe')"))
    pg.fill(f'#fe_{j}_k','rozp'); pg.press(f'#fe_{j}_k','Tab'); pg.wait_for_timeout(100); pg.select_option('#e_kat','hig'); pg.click('#e_save'); pg.wait_for_timeout(300)
    nid=pg.evaluate("ALL.find(p=>p.name==='Wybielanie nakładkowe').id")
    t.chk('nowa procedura zapisana jako „własna”, v1, w kategorii Higienizacja', 'własna' in tx(pg,f'#t-{nid}') and 'v1' in tx(pg,f'#t-{nid}') and pg.evaluate(f"PROC.get('{nid}').kat")=='hig')
    tab(pg,'cen'); t.chk('…pojawia się w cenniku', pg.locator(f'[data-cc="{nid}"]').count()==1)
    pg.fill(f'[data-cc="{nid}"]','800'); pg.press(f'[data-cc="{nid}"]','Tab')
    tab(pg,'wiz'); pg.fill('#p_q','wybiel'); pg.wait_for_timeout(250); pg.click(f'button[data-add="{nid}"]')
    pg.fill(fid(pg,0,'rozp'),'przebarwienia'); pg.fill(fid(pg,0,'przebieg'),'wydanie nakładek i żelu')
    t.chk('własna procedura w wizycie: opis i cena 800 zł', txt(pg)=='Rozpoznanie: przebarwienia.\nPrzebieg: wydanie nakładek i żelu.' and '800,00 zł' in tx(pg,'#sum'), txt(pg))
    pg.click('#b_save'); pg.wait_for_function("S.visits.size===2"); v2=pg.evaluate("V.id"); s2=txt(pg); pg.click('#b_new')
    # duplikat + ukrywanie + usuwanie własnej
    tab(pg,'tpl'); pg.click('#t-hig-skaling button[data-a="tdup"]'); t.chk('„Duplikuj” otwiera kopię jako nową procedurę', pg.input_value('#e_name')=='Skaling (kopia)')
    pg.click('#e_save'); pg.wait_for_timeout(300); t.chk('…kopia zapisana, oryginał bez zmian', pg.evaluate("ALL.filter(p=>p.name.startsWith('Skaling')).length")==2 and 'zmieniona' not in tx(pg,'#t-hig-skaling'))
    pg.click('#t-zach-mleczny button[data-a="thide"]'); tab(pg,'wiz'); pg.click('button[data-a="pickshow"]') if pg.locator('button[data-a="pickshow"]').count() else None
    t.chk('ukryta procedura znika z listy przy wizycie', pg.locator('button[data-add="zach-mleczny"]').count()==0 and pg.locator('button[data-add="zach-staly"]').count()==1)
    tab(pg,'tpl'); pg.click('#t-zach-mleczny button[data-a="thide"]')
    pg.click(f'#t-{nid} button[data-a="tdel"]'); pg.click(f'#t-{nid} button[data-a="tdel"]'); pg.wait_for_timeout(300)
    t.chk('usunięcie własnej procedury (2 kliknięcia)', not pg.evaluate(f"PROC.has('{nid}')"))
    tab(pg,'hist'); pg.click(f'#h-{v2} button[data-a="hopen"]'); pg.wait_for_timeout(300)
    t.chk('wizyta z usuniętą procedurą: zapisany tekst i formularz (z migawki szablonu) zostają', txt(pg)==s2 and pg.locator(fid(pg,0,'przebieg')).count()==1)
    pg.click('#b_new')
    # ---------- ulubione ----------
    tab(pg,'wiz'); pg.click('button[data-fav="endo-jedno"]')
    t.chk('★ przy procedurze → grupa „Ulubione” na górze listy', pg.locator('.pw-kh:has-text("Ulubione") + .pw-plist button[data-add="endo-jedno"]').count()==1)
    # ---------- zestawy ----------
    tab(pg,'cen'); pg.click('button[data-cg="-"]'); pg.fill('#c_pct','50'); pg.press('#c_pct','Tab')
    for pid,c in [('chir-ekstrakcja','300'),('diag-kontrolna','100'),('hig-skaling','200')]: pg.fill(f'[data-cc="{pid}"]',c); pg.press(f'[data-cc="{pid}"]','Tab')
    tab(pg,'zes')
    t.chk('2 przykładowe zestawy przy pierwszym uruchomieniu', pg.evaluate("ZES.list.filter(z=>z.ex).length")==2)
    pg.click('#zs_new'); pg.click('#zs_save'); t.chk('zestaw bez nazwy → komunikat', 'Podaj nazwę zestawu.' in pg.inner_text('#main'))
    pg.fill('#zs_name','Ekstrakcja + kontrola'); pg.fill('#zs_kat','Chirurgia')
    for pid in ['diag-kontrolna','chir-ekstrakcja','hig-skaling']: pg.select_option('#zs_add',pid); pg.click('button[data-a="zadd"]')
    pg.locator('#zs_list li[data-zi="1"]').drag_to(pg.locator('#zs_list li[data-zi="0"]')); pg.wait_for_timeout(150)
    t.chk('przeciąganie zmienia kolejność (ekstrakcja na początek)', pg.evaluate("S.zed.items.join(',')")=='chir-ekstrakcja,diag-kontrolna,hig-skaling', pg.evaluate("S.zed.items"))
    pg.click('#zs_list button[data-a="zdown"][data-j="0"]'); pg.click('#zs_list button[data-a="zup"][data-j="1"]')
    pg.click('#zs_list button[data-a="zrm"][data-j="2"]')
    t.chk('↑ ↓ i ✕: ekstrakcja, kontrola; podgląd wg cennika „bez gabinetu” 400 / 200 zł', pg.evaluate("S.zed.items.join(',')")=='chir-ekstrakcja,diag-kontrolna' and '400,00 zł' in tx(pg,'#main') and '200,00 zł' in tx(pg,'#main'), tx(pg,'#main')[-200:])
    pg.check('#zs_fav'); pg.click('#zs_save'); pg.wait_for_timeout(300)
    zid=pg.evaluate("ZES.list.find(z=>z.name==='Ekstrakcja + kontrola').id")
    t.chk('zestaw zapisany (ulubiony, kategoria Chirurgia), zaszyfrowany', 'Ekstrakcja + kontrola' in tx(pg,f'#z-{zid}') and pg.evaluate(f"ZES.list.find(z=>z.id==='{zid}').fav")==True and bool(re.fullmatch(r'v1:.+',pg.evaluate("G.store('kv').raw('pryw:zestawy')") or '')))
    pg.fill('#zs_q','kontrola'); pg.wait_for_timeout(300)
    t.chk('wyszukiwanie zestawów (po nazwie i procedurach)', pg.locator('.pw-tl[id^="z-"]').count()==1); pg.fill('#zs_q',''); pg.wait_for_timeout(300)
    pg.click(f'#z-{zid} button[data-a="zdup"]'); t.chk('duplikat zestawu', pg.evaluate("ZES.list.filter(z=>z.name==='Ekstrakcja + kontrola (kopia)').length")==1)
    dup=pg.evaluate("ZES.list.find(z=>z.name.endsWith('(kopia)')).id"); pg.click(f'#z-{dup} button[data-a="zdel"]'); pg.click(f'#z-{dup} button[data-a="zdel"]'); pg.wait_for_timeout(200)
    t.chk('usunięcie zestawu (2 kliknięcia)', pg.evaluate("ZES.list.some(z=>z.id==='"+dup+"')")==False)
    tab(pg,'wiz'); pg.select_option('#v_gab','-'); pg.click(f'button[data-zadd="{zid}"]'); pg.wait_for_timeout(200)
    t.chk('zestaw w wizycie: 2 procedury z cenami (400 / 200 zł)', pg.evaluate("V.items.map(i=>i.pid).join(',')")=='chir-ekstrakcja,diag-kontrolna' and '400,00 zł' in tx(pg,'#sum') and '200,00 zł' in tx(pg,'#sum'))
    pg.fill('#pr_'+pg.evaluate("V.items[1].u")+'_c','150'); pg.wait_for_timeout(100)
    t.chk('…procedury z zestawu dalej edytowalne (kontrola 150 zł → 450 / 225 zł)', '450,00 zł' in tx(pg,'#sum') and '225,00 zł' in tx(pg,'#sum'))
    tab(pg,'zes'); pg.click(f'#z-{zid} button[data-a="zedit"]'); pg.fill('#zs_name','Ekstrakcja i kontrola'); pg.click('#zs_save'); tab(pg,'wiz')
    t.chk('zmiana zestawu nie zmienia procedur dodanych już do wizyty', pg.evaluate("V.items.length")==2 and '450,00 zł' in tx(pg,'#sum'))
    pg.click('#b_new'); pg.click('#b_new')
    # ---------- tryb szybkiej wizyty ----------
    pg.click('#b_quick'); pg.wait_for_timeout(100)
    t.chk('tryb szybki: na górze ulubione i zestawy, pełna lista zwinięta', pg.locator('button[data-add="endo-jedno"]').count()==1 and pg.locator(f'button[data-zadd="{zid}"]').count()==1 and pg.locator('button[data-add="zach-staly"]').count()==0)
    pg.click(f'button[data-zadd="{zid}"]'); n_all=pg.evaluate("procOf(V.items[0]).fields.filter(f=>visible(f,V.items[0].vals)).length"); n_shown=pg.locator(f'#it-{pg.evaluate("V.items[0].u")} .pw-f').count()
    t.chk('tryb szybki: widać tylko pola wymagane i wypełnione (ekstrakcja: 2 z '+str(n_all)+')', n_shown==2, n_shown)
    pg.click(f'#it-{pg.evaluate("V.items[0].u")} button[data-a="ifull"]')
    t.chk('„Pokaż wszystkie pola” odsłania resztę', pg.locator(f'#it-{pg.evaluate("V.items[0].u")} .pw-f').count()==n_all)
    pg.fill(fid(pg,0,'zab'),'38'); pg.fill(fid(pg,0,'rozp'),'ząb zaklinowany'); pg.fill(fid(pg,1,'cel'),'kontrola po ekstrakcji 38')
    pg.click('#b_cs'); pg.wait_for_function("S.visits.size===3"); pg.wait_for_timeout(200)
    clip=pg.evaluate("navigator.clipboard.readText()")
    t.chk('„Kopiuj i zapisz”: wizyta zapisana, opis w schowku', clip==txt(pg) and clip.startswith('Ekstrakcja zęba 38.') and pg.evaluate("!dirty()"), clip[:80])
    pg.reload(); ready(pg)
    t.chk('po ponownym otwarciu: tryb szybki, ulubione, zestawy i szablony na miejscu', pg.evaluate("S.quick")==True and pg.evaluate("UK.fav.includes('endo-jedno')") and pg.evaluate("ZES.list.some(z=>z.name==='Ekstrakcja i kontrola')") and pg.evaluate("PROC.get('zach-staly')._ver")==4)
    t.chk('brak błędów JS', not errs, errs[:3])
    t.done('T14 szablony, zestawy, ulubione, tryb szybki'); b.close()
